class entity;

template <class T>
class singleton_ptr
{
    T* p;
public:
    operator T*() const { return p; }
};

class SoundScriptManager
{
    static singleton_ptr<SoundScriptManager> instance;
public:
    static inline SoundScriptManager* inst() { return instance; }
    int playEvent(int type, entity* e = 0, float fadeInTime = 0);
};

class PanelQuad
{
public:
    virtual ~PanelQuad();
    virtual void Init(float, float, float, float, float, float, float, float,
                      float, float, float, float, float, const void*);
    virtual void TurnOn(bool on);
    virtual void SetLayer(int);
    virtual void Rotate(float);
    virtual void Rotate(float, float, float);
    virtual void Update(float);
    virtual void Draw(int = 0, float = -1.0f);
    virtual void SetColor(float, float, float, float);
    virtual void SetColor(unsigned int);
    virtual void SetZ(float);
    virtual void SetUV(float, float, float, float);
    virtual bool IsOn() const;
    virtual void SetPos(float, float, float, float);
    virtual void SetPos(float, float);
    virtual void SetPos(float, float, float, float, float, float, float, float);
    virtual void GetPos(float&, float&, float&, float&);
    virtual void SetCenterX(float);
    virtual void SetCenterY(float);
    virtual void SetCenterPos(float, float);
    virtual void GetCenterPos(float&, float&);
    virtual void SetCenterPosQuadOnly(float, float);
    virtual float GetWidth();
    virtual float GetHeight();
    virtual float GetWidthA();
    virtual float GetHeightA();
    virtual void SetClip(bool);
    virtual void SetClip(const void&);
    virtual void GetFade(int& f, float& alpha, float& timer);
    virtual void SetFade(int f, float alpha, float timer);
};

class FEMenuEntry
{
public:
    int entry_num;
};

class FEGraphicalMenu
{
public:
    void OnDown(int c);
};

class OptionsMenu : public FEGraphicalMenu
{
    char padding_to_highlighted[0x4c];
    FEMenuEntry* highlighted;
    char padding_to_lights[0x1c8];
    PanelQuad* lights[11];
public:
    void OnDown(int c);
};

enum { SS_FE_UPDOWN = 25 };

__asm__(".equ _18SoundScriptManager$instance, 0x0045B4A0");
__asm__(".equ playEvent__18SoundScriptManageriP6entityf, 0x0031C380");
__asm__(".equ OnDown__15FEGraphicalMenui, OnDown__6FEMenui");
__asm__(".equ OnDown__6FEMenui, 0x001DAA80");

void OptionsMenu::OnDown(int c)
{
	SoundScriptManager::inst()->playEvent(SS_FE_UPDOWN);
	lights[highlighted->entry_num]->TurnOn(false);
	int fade;
	float alpha, timer;
	lights[highlighted->entry_num]->GetFade(fade, alpha, timer);
	FEGraphicalMenu::OnDown(c);
	lights[highlighted->entry_num]->TurnOn(true);
	lights[highlighted->entry_num]->SetFade(fade, alpha, timer);
}
